import Decimal from "decimal.js";
import type { MonthsMetricResult } from "./result";

const FORMULA_ID = "cac_payback.cumulative_contribution_margin.v1";

function parseDecimal(value: string, field: string): Decimal {
  const parsed = new Decimal(value);
  if (!parsed.isFinite()) throw new Error(`${field} must be finite`);
  return parsed;
}

/**
 * Calculates CAC payback from cumulative contribution margin generated by one
 * acquired customer or one acquisition cohort. Fixed company OPEX is excluded;
 * variable support, payment fees, usage infrastructure, onboarding delivery,
 * refunds, and other customer-level variable costs must be included upstream.
 */
export function calculateCacPayback(
  cac: string,
  monthlyContributionMargin: readonly string[],
): MonthsMetricResult {
  const horizonMonths = monthlyContributionMargin.length;
  const acquisitionCost = parseDecimal(cac, "cac");

  if (acquisitionCost.isNegative()) {
    return {
      status: "INVALID_INPUTS",
      months: null,
      horizonMonths,
      formulaId: FORMULA_ID,
      reasonCode: "CAC_NEGATIVE",
    };
  }

  if (horizonMonths === 0) {
    return {
      status: "INSUFFICIENT_INPUTS",
      months: null,
      horizonMonths,
      formulaId: FORMULA_ID,
      reasonCode: "NO_CONTRIBUTION_SERIES",
    };
  }

  let cumulative = acquisitionCost.negated();
  if (cumulative.greaterThanOrEqualTo(0)) {
    return {
      status: "VALUE",
      months: "0",
      horizonMonths,
      formulaId: FORMULA_ID,
      reasonCode: null,
    };
  }

  for (let index = 0; index < monthlyContributionMargin.length; index += 1) {
    const current = parseDecimal(monthlyContributionMargin[index]!, `monthlyContributionMargin[${index}]`);
    const before = cumulative;
    cumulative = cumulative.plus(current);

    if (cumulative.greaterThanOrEqualTo(0)) {
      const completedMonths = new Decimal(index);
      const fraction = current.greaterThan(0)
        ? before.negated().dividedBy(current)
        : new Decimal(1);
      return {
        status: "VALUE",
        months: completedMonths.plus(fraction).toDecimalPlaces(2).toString(),
        horizonMonths,
        formulaId: FORMULA_ID,
        reasonCode: null,
      };
    }
  }

  return {
    status: "NOT_ACHIEVED_WITHIN_HORIZON",
    months: null,
    horizonMonths,
    formulaId: FORMULA_ID,
    reasonCode: "CUMULATIVE_CONTRIBUTION_BELOW_CAC",
  };
}
